package com.karavan.ates;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.provider.Settings;
import android.view.*;
import android.widget.*;
import java.text.SimpleDateFormat;
import java.util.*;

public class MainActivity extends Activity {
 static final int BG=0xff201b18, PANEL=0xff302722, MUTED=0xffc0ada0, WHITE=0xfffff2e3, GREEN=0xffa8d6b5, GOLD=0xffffc078, RED=0xffff9a8e;
 static boolean visible=false;
 final Handler handler=new Handler(Looper.getMainLooper());
 LinearLayout root,grid,regions,filters; TextView clock,notice,results,revenue; long reportMinute=-1; TextView[] stats=new TextView[4];
 int tab=0,statusFilter=0; boolean urgent=true; String signature="";
 final ArrayList<Card> cards=new ArrayList<>();
 final Runnable tick=()->{refresh();handler.postDelayed(this.tick,1000);};
 class Card {int id; int style=-1; LinearLayout panel;TextView badge,time,detail;ProgressBar progress;Card(int n){id=n;}}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 GradientDrawable shape(int color,int border){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(16));if(border!=0)d.setStroke(dp(1),border);return d;}
 GradientDrawable gradient(int first,int last,int border){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{first,last});d.setCornerRadius(dp(20));if(border!=0)d.setStroke(dp(1),border);return d;}
 TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(dp(8),dp(5),dp(8),dp(5));return t;}
 TextView bold(String s,int size,int color){TextView t=text(s,size,color);t.setTypeface(null,Typeface.BOLD);return t;}
 Button button(String s,boolean selected,Runnable action){Button b=new Button(this);b.setText(s);b.setTextSize(14);b.setMaxLines(2);b.setAutoSizeTextTypeUniformWithConfiguration(11,14,1,android.util.TypedValue.COMPLEX_UNIT_SP);b.setAllCaps(false);b.setTextColor(selected?BG:WHITE);b.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x30ffffff),selected?gradient(0xffffd39a,0xffdca06c,0):shape(0xff3b3029,0xff615044),null));b.setElevation(dp(selected?3:0));b.setMinHeight(dp(48));b.setPadding(dp(8),dp(4),dp(8),dp(4));b.setOnClickListener(v->action.run());return b;}
 void weighted(LinearLayout row,View v,int height){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,height,1);p.setMargins(dp(3),dp(4),dp(3),dp(4));row.addView(v,p);}
 public void onCreate(Bundle state){super.onCreate(state);if(state!=null){tab=state.getInt("tab");statusFilter=state.getInt("filter");urgent=state.getBoolean("urgent",true);}getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);setVolumeControlStream(android.media.AudioManager.STREAM_ALARM);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},1);draw();}
 protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putInt("tab",tab);state.putInt("filter",statusFilter);state.putBoolean("urgent",urgent);}
 protected void onResume(){super.onResume();visible=true;for(int i=0;i<50;i++)Timers.schedule(this,i);handler.removeCallbacks(tick);handler.post(tick);}
 protected void onPause(){super.onPause();visible=false;handler.removeCallbacks(tick);}
 @SuppressWarnings("deprecation")
 void draw(){
  root=new LinearLayout(this);root.setOrientation(1);root.setBackground(new EmberBackdrop());root.setPadding(dp(14),dp(28),dp(14),dp(12));ScrollView page=new ScrollView(this);page.setFillViewport(true);page.setBackground(new EmberBackdrop());page.addView(root);setContentView(page);page.setOnApplyWindowInsetsListener((v,insets)->{page.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets.consumeSystemWindowInsets();});root.setPadding(dp(12),dp(12),dp(12),dp(16));
  LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(dp(12),dp(12),dp(12),dp(12));header.setBackground(gradient(0xff543629,0xff2c241e,0xff8c6242));header.setElevation(dp(4));LinearLayout brand=new LinearLayout(this);brand.setOrientation(1);TextView wordmark=bold("Karavan Coffee",26,WHITE);wordmark.setSingleLine(true);wordmark.setAutoSizeTextTypeUniformWithConfiguration(14,26,1,android.util.TypedValue.COMPLEX_UNIT_SP);brand.addView(wordmark);brand.addView(text("ATEŞ TAKİP PANELİ",10,GOLD));TextView emblem=bold("♨",36,GOLD);emblem.setGravity(Gravity.CENTER);emblem.setBackground(shape(0xff3a2920,0xff94663e));LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(dp(48),dp(48));ep.setMargins(0,0,dp(8),0);header.addView(emblem,ep);header.addView(brand,new LinearLayout.LayoutParams(0,-2,1));clock=text("",12,MUTED);clock.setGravity(Gravity.RIGHT);root.addView(header);root.addView(clock,new LinearLayout.LayoutParams(-1,-2));revenue=bold("",16,GOLD);revenue.setBackground(shape(0xff3c3026,0xff785b3f));revenue.setPadding(dp(12),dp(12),dp(12),dp(12));revenue.setOnClickListener(v->showRevenue());root.addView(revenue);
  LinearLayout overview=new LinearLayout(this);String[] labels={"AKTİF","BOŞ","SON 5 DK","SÜRESİ DOLDU"};for(int i=0;i<4;i++){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(5),dp(5),dp(5),dp(5));box.setBackground(gradient(0xff423329,0xff302722,0xff66503e));box.setElevation(dp(2));stats[i]=bold("0",27,i==1?GREEN:i==2?GOLD:i==3?RED:WHITE);box.addView(stats[i]);box.addView(text(labels[i],10,MUTED));weighted(overview,box,-2);}root.addView(overview);
  notice=text("",12,GOLD);notice.setPadding(dp(12),dp(10),dp(12),dp(10));notice.setBackground(shape(0x99433528,0xff64503c));LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(-1,-2);np.setMargins(dp(3),dp(8),dp(3),dp(8));root.addView(notice,np);
  regions=new LinearLayout(this);root.addView(regions);filters=new LinearLayout(this);root.addView(filters);navigation();
  results=text("",13,MUTED);root.addView(results);LinearLayout toolbar=new LinearLayout(this);weighted(toolbar,button("Sıralama",false,()->{urgent=!urgent;signature="";refresh();}),dp(48));weighted(toolbar,button("Kazançlar",false,()->showRevenue()),dp(48));weighted(toolbar,button("Ses / izinler",false,()->settings()),dp(48));root.addView(toolbar);
  grid=new LinearLayout(this);grid.setOrientation(1);root.addView(grid);refresh();
 }
 void navigation(){regions.removeAllViews();filters.removeAllViews();String[] names={"Tümü · 50","Sağ · 20","Sol · 20","Orta · 10"};for(int j=0;j<4;j++){final int k=j;weighted(regions,button(names[j],tab==j,()->{tab=k;navigation();signature="";refresh();}),dp(48));}String[] states={"Tüm ateşler","Aktif ateşler","Boş ateşler","Uyarılar"};for(int j=0;j<4;j++){final int k=j;weighted(filters,button(states[j],statusFilter==j,()->{statusFilter=k;navigation();signature="";refresh();}),dp(48));}}
 void buildCards(ArrayList<Integer> visible){grid.removeAllViews();cards.clear();int width=getResources().getConfiguration().screenWidthDp;int columns=width>=1100?4:width>=760?3:width>=500?2:1;LinearLayout row=null;for(int i=0;i<visible.size();i++){if(i%columns==0){row=new LinearLayout(this);grid.addView(row);}int id=visible.get(i);Card c=new Card(id);cards.add(c);c.panel=new LinearLayout(this);c.panel.setOrientation(1);c.panel.setPadding(dp(14),dp(14),dp(14),dp(14));c.panel.setElevation(dp(4));weighted(row,c.panel,-2);
   LinearLayout top=new LinearLayout(this);top.addView(bold("♨  "+Timers.name(id),23,WHITE),new LinearLayout.LayoutParams(0,-2,1));c.badge=text("",10,GREEN);c.badge.setPadding(dp(9),dp(6),dp(9),dp(6));top.addView(c.badge);c.panel.addView(top);
   c.time=bold("",36,WHITE);c.time.setTypeface(Typeface.create("sans-serif-light",Typeface.NORMAL));c.time.setPadding(dp(8),dp(16),dp(8),dp(4));c.panel.addView(c.time);c.detail=text("",12,MUTED);c.panel.addView(c.detail);
   c.progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);c.progress.setMax(1000);LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(-1,dp(5));pp.setMargins(dp(8),dp(10),dp(8),dp(16));c.panel.addView(c.progress,pp);
   boolean active=Timers.end(this,id)!=0;c.panel.addView(button(active?"＋  Ateşi uzat":"♨  Ateşi başlat",true,()->choose(id)));
   LinearLayout actions=new LinearLayout(this);if(active){weighted(actions,button("＋1 saat",false,()->confirm(id,60)),dp(48));weighted(actions,button("Boşalt",false,()->clear(id)),dp(48));}else{actions.addView(text("1 saat = 200 TL",13,GOLD));}c.panel.addView(actions);
  }
  if(row!=null)for(int i=visible.size()%columns;i>0&&i<columns;i++)weighted(row,new View(this),1);
  if(visible.isEmpty()){TextView empty=bold("Bu bölümde ateş bulunmuyor\nBaşka bir filtre seçebilirsiniz.",20,MUTED);empty.setGravity(Gravity.CENTER);empty.setPadding(0,dp(48),0,0);grid.addView(empty);}
 }
 void refresh(){if(grid==null)return;if(visible)AlertSound.checkActiveTimers(this);long now=System.currentTimeMillis();if(reportMinute!=now/60000){reportMinute=now/60000;updateRevenue(now);}int active=0,near=0,expired=0;ArrayList<Integer> visible=new ArrayList<>();for(int id=0;id<50;id++){long end=Timers.end(this,id);if(end!=0){active++;if(end<=now)expired++;else if(end-now<=300000)near++;}if(tab==1&&id>=20||tab==2&&(id<20||id>=40)||tab==3&&id<40)continue;if(statusFilter==1&&end==0||statusFilter==2&&end!=0||statusFilter==3&&(end==0||end-now>300000))continue;visible.add(id);}
  if(urgent)Collections.sort(visible,(a,b)->{long ea=Timers.end(this,a),eb=Timers.end(this,b);int compare=Long.compare(ea==0?Long.MAX_VALUE:ea,eb==0?Long.MAX_VALUE:eb);return compare!=0?compare:Integer.compare(a,b);});String next=visible.toString();if(!signature.equals(next)){signature=next;buildCards(visible);}
  stats[0].setText(""+active);stats[1].setText(""+(50-active));stats[2].setText(""+near);stats[3].setText(""+expired);SimpleDateFormat wallClock=new SimpleDateFormat("HH:mm:ss · d MMMM EEEE",new Locale("tr"));wallClock.setTimeZone(TimeZone.getTimeZone("Europe/Istanbul"));clock.setText(wallClock.format(new Date(now)));notice.setText(expired>0?expired+" ateşin süresi doldu. Uzatın veya alanı boşaltın.":near>0?near+" ateşin bitmesine 5 dakikadan az kaldı.":"● Tüm alanlar takipte · Veriler bu cihazda saklanıyor");notice.setTextColor(expired>0?RED:near>0?GOLD:GREEN);results.setText(visible.size()+" alan · "+(urgent?"Önce bitenler":"Alan sırası"));
  for(Card c:cards){long end=Timers.end(this,c.id),left=end-now;int color=end==0?GREEN:left<=0?RED:left<=300000?GOLD:GREEN;int style=end==0?0:left<=0?3:left<=300000?2:1;if(c.style!=style){c.style=style;c.panel.setBackground(gradient(style==3?0xff513029:style==2?0xff51402a:style==1?0xff3d352b:0xff302e26,0xff26211d,end!=0&&left<=300000?color:0xff665140));c.badge.setBackground(shape(style==3?0xff66372f:style==2?0xff66502d:0xff394438,0));}c.badge.setText(end==0?"BOŞ":left<=0?"SÜRE DOLDU":left<=300000?"SON 5 DK":"AKTİF");c.badge.setTextColor(color);c.time.setTextColor(color);c.time.setText(end==0?"Hazır":left<=0?"Süre doldu":TimerMath.remaining(left));c.detail.setText(end==0?"1 saat 200 TL · Süre seçerek başlatın":(left<=0?"Boşaltılana kadar aktif kalır":"Bitiş "+new SimpleDateFormat("HH:mm · dd MMM",new Locale("tr")).format(new Date(end)))+"\nKaydedilen ücret: "+BusinessClock.money(getSharedPreferences("timers",0).getLong("fee"+c.id,0)));long start=getSharedPreferences("timers",0).getLong("start"+c.id,now);long total=Math.max(1,end-start);c.progress.setProgress(end==0?0:(int)Math.max(0,Math.min(1000,left*1000/total)));c.progress.setProgressBackgroundTintList(android.content.res.ColorStateList.valueOf(0xff504539));c.progress.setProgressTintList(android.content.res.ColorStateList.valueOf(color));}
 }
 void choose(int id){boolean active=Timers.end(this,id)!=0;String[] options=new String[7];for(int j=0;j<7;j++)options[j]=(j+1)+" saat"+(active?" ekle":"")+" · "+BusinessClock.money(BusinessClock.price((j+1)*60));new AlertDialog.Builder(this).setTitle(Timers.name(id)+(active?" · Ateşi uzat":" · Süre seç")).setItems(options,(d,w)->confirm(id,(w+1)*60)).setNegativeButton("Vazgeç",null).show();}
 void confirm(int id,int minutes){long expected=Timers.end(this,id);boolean active=expected!=0;new AlertDialog.Builder(this).setTitle(Timers.name(id)+(active?" uzatılsın mı?":" başlatılsın mı?")).setMessage(minutes+" dakika · "+BusinessClock.money(BusinessClock.price(minutes))+"\n"+(active?"eklenecek. Süre dolmuşsa şu andan başlar.":"boyunca takip edilecek.")).setPositiveButton(active?"Uzat":"Başlat",(d,w)->{long now=System.currentTimeMillis();if(!Ledger.book(this,id,minutes,now)){new AlertDialog.Builder(this).setTitle("İşlem kaydedilemedi").setMessage("Süre ve kazanç kaydı tamamlanamadı. Kayıtları silmeden yeniden deneyin.").setPositiveButton("Tamam",null).show();return;}reportMinute=-1;((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).cancel(id);signature="";refresh();Toast.makeText(this,Timers.name(id)+" · Süre kaydedildi",Toast.LENGTH_SHORT).show();}).setNegativeButton("Vazgeç",null).show();}
 void clear(int id){new AlertDialog.Builder(this).setTitle(Timers.name(id)+" boşaltılsın mı?").setMessage("Bu alanın sayacı ve planlanmış uyarıları kaldırılacak. Kazanç kaydı korunur; bu işlem iade yapmaz.").setPositiveButton("Alanı boşalt",(d,w)->{Timers.save(this,id,0);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).cancel(id);signature="";refresh();}).setNegativeButton("Vazgeç",null).show();}
 void updateRevenue(long now){try{long[] totals=Ledger.totals(this,now);revenue.setText("Günlük  "+BusinessClock.money(totals[0])+"   ›\nAylık  "+BusinessClock.money(totals[1])+"  ·  Toplam  "+BusinessClock.money(totals[2]));}catch(org.json.JSONException e){revenue.setText("Kazanç kaydı okunamadı · Verileri silmeyin");}}
 void showRevenue(){
  try{
   long now=System.currentTimeMillis();long[] sums=Ledger.totals(this,now);
   LinearLayout body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(16),dp(12),dp(16),dp(12));body.setBackgroundColor(BG);
   body.addView(bold("Günlük: "+BusinessClock.money(sums[0]),23,GOLD));body.addView(text("İş günü: "+BusinessClock.day(now)+" · 02.00 → 02.00",13,MUTED));body.addView(bold("Aylık: "+BusinessClock.money(sums[1]),20,WHITE));body.addView(bold("Toplam: "+BusinessClock.money(sums[2]),20,WHITE));
   body.addView(text("Saatlik ücret 200 TL. Başlatma ve uzatmalar işlem anında kazanca eklenir. Türkiye saati kullanılır. Bu tutarlar tahsilat takibi değildir. Alanı boşaltmak kazancı silmez. Önceki sürümdeki kullanımlar dahil değildir.",13,MUTED));
   body.addView(bold("Son işlemler",18,GOLD));org.json.JSONArray entries=Ledger.entries(this);
   if(entries.length()==0)body.addView(text("Henüz ücretli işlem yok.",15,WHITE));
   SimpleDateFormat stamp=new SimpleDateFormat("dd MMM HH:mm",new Locale("tr"));stamp.setTimeZone(TimeZone.getTimeZone("Europe/Istanbul"));
   for(int i=entries.length()-1;i>=Math.max(0,entries.length()-30);i--){org.json.JSONObject row=entries.getJSONObject(i);body.addView(text(Timers.name(row.getInt("area"))+" · "+row.getString("kind")+" · "+BusinessClock.money(row.getLong("amount"))+"\n"+stamp.format(new Date(row.getLong("at")))+" · "+row.getInt("minutes")/60+" saat",14,WHITE));}
   ScrollView scroll=new ScrollView(this);scroll.addView(body);new AlertDialog.Builder(this).setTitle("Kazanç raporu").setView(scroll).setPositiveButton("Kapat",null).show();
  }catch(org.json.JSONException e){new AlertDialog.Builder(this).setTitle("Kazanç kaydı okunamadı").setMessage("Verileri silmeyin; kayıtları incelemek gerekiyor.").setPositiveButton("Tamam",null).show();}
 }
 String soundStatus(){
  android.media.AudioManager audio=(android.media.AudioManager)getSystemService(AUDIO_SERVICE);
  boolean notifications=((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).areNotificationsEnabled();
  boolean exact=Build.VERSION.SDK_INT<31||((AlarmManager)getSystemService(ALARM_SERVICE)).canScheduleExactAlarms();
  return "Alarm sesi: "+audio.getStreamVolume(android.media.AudioManager.STREAM_ALARM)+" / "+audio.getStreamMaxVolume(android.media.AudioManager.STREAM_ALARM)+"\nBildirimler: "+(notifications?"Açık":"Kapalı — izin verin")+"\nKesin zamanlama: "+(exact?"Açık":"Kapalı — izin verin")+"\n\nAçık uygulamada doğrudan alarm sesi çalar. Arka planda sesli bildirim kullanılır. Ses dene düğmesi aynı alarm sesini 5 saniye çalar. Telefonun Alarm sesini yükseltin; Rahatsız Etmeyin ayarını kontrol edin.";
 }
 void settings(){new AlertDialog.Builder(this).setTitle("Ses ve zamanlama").setMessage(soundStatus()).setPositiveButton("Zamanlama izni",(d,w)->{if(Build.VERSION.SDK_INT>=31)startActivity(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName())));}).setNeutralButton("Ses dene",(d,w)->{AlertSound.play(this);}).setNegativeButton("Bildirim ayarları",(d,w)->startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()))).show();}
}
